; __k3_divmod: r0 = r0 / r1, r1 = r0 % r1 (toward zero)
__k3_divmod:
    brnz r1, .Ldiv_go
    ldi r0, #0
    ldi r1, #0
    ret
.Ldiv_go:
    mov r2, r0
    cmpi r2, #0
    push r2
    mov r2, r1
    cmpi r2, #0
    push r2
    brn r0, .Ldiv_nega
    jmp .Ldiv_absa
.Ldiv_nega:
    neg r0, r0
.Ldiv_absa:
    brn r1, .Ldiv_negb
    jmp .Ldiv_absb
.Ldiv_negb:
    neg r1, r1
.Ldiv_absb:
    mov r2, r0
    ldi r0, #0
.Ldiv_loop:
    sub r2, r2, r1
    brn r2, .Ldiv_undo
