    jmp .Ldiv_loop
.Ldiv_undo:
    add r2, r2, r1
    pop r4
    pop r1
    mul r4, r1, r4
    brn r4, .Ldiv_negq
    jmp .Ldiv_qdone
.Ldiv_negq:
    neg r0, r0
.Ldiv_qdone:
